  const workspaceTrusted = workspaceMayHaveTriggers(workspace);
  const id: TriggerTrustId = { scope: workspace, key: spec ? spec.id : "" };
  const status = spec ? triggerTrustStatus(entries, id.key, id.scope, currentSha256) : "ABSENT";
